<script setup>
import {ref,watch} from 'vue';
import {request} from './workbench-api';
const props=defineProps({documentId:{type:String,required:true}});
const items=ref([]),error=ref(''),focus=ref({});let sequence=0;
const labels={recovered_table:'已恢复表格',graphic_reference:'完整图形依据',superseded:'由已核对表格替代'};
watch(()=>props.documentId,async id=>{const seq=++sequence;items.value=[];error.value='';try{const r=await request(`/documents/${id}/structures`);if(seq===sequence)items.value=r.items;}catch(e){if(seq===sequence)error.value=e.message;}},{immediate:true});
function marker(entry){const c=focus.value[entry.candidate_id];if(!c?.bbox)return {};const [x,y,x1,y1]=c.bbox;const [w,h]=entry.table.page_size;return {left:x/w*100+'%',top:y/h*100+'%',width:(x1-x)/w*100+'%',height:(y1-y)/h*100+'%'};}
</script>
<template><section v-if="items.length||error" class="wb-structure-evidence"><h4>结构恢复与图形处置 · AI 来源审核</h4><p v-if="error" role="alert">{{error}}</p><p>原始正文和退回网格均保留。图形的数值、箭头和颜色关系以完整原页为准；空格不补值。</p><details v-for="entry in items" :key="entry.candidate_id"><summary>{{labels[entry.disposition]}} · {{entry.candidate_id}}</summary><p>{{entry.note}}</p><p>{{entry.table_note}}</p><div class="compare"><div class="page"><img :src="`/api/v2/workbench/documents/${documentId}/structures/${entry.candidate_id}/preview`" :alt="entry.candidate_id+' 完整来源页'" loading="lazy"/><div v-if="focus[entry.candidate_id]?.bbox" class="marker" :style="marker(entry)"></div></div><div v-if="entry.table" class="cells"><p>点击单元格查看原页位置。展开表头标记为 AI 规范化，不冒充原始单元格边框。</p><table><tbody><tr v-for="r in entry.table.row_count" :key="r"><td v-for="c in entry.table.cells.filter(c=>c.row===r-1)" :key="c.cell_id" :rowspan="c.rowspan" :colspan="c.colspan" @click="focus[entry.candidate_id]=c">{{c.text||'〔原空白〕'}}</td></tr></tbody></table><pre v-if="focus[entry.candidate_id]">{{JSON.stringify(focus[entry.candidate_id].locator,null,2)}}</pre></div></div><p v-if="entry.formula_transcription">公式原图转写：{{entry.formula_transcription}}（保留原图，不执行求值）</p><a :href="`/api/v2/workbench/documents/${documentId}/source?revision_id=${entry.revision_id}`">下载绑定版本的原件</a><small> SHA256 {{entry.source_sha256}}</small></details></section></template>
<style scoped>details{border:1px solid #ccd5df;border-radius:8px;padding:12px;margin:10px 0}summary{cursor:pointer;overflow-wrap:anywhere}.compare{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.page{position:relative;align-self:start}.page img{display:block;width:100%}.marker{position:absolute;border:2px solid #df6c17;background:#ffdb6744;pointer-events:none;box-sizing:border-box}.cells{overflow:auto;max-height:700px}table{border-collapse:collapse;font-size:13px}td{border:1px solid #aab;padding:6px;white-space:pre-wrap;cursor:pointer}td:hover{background:#fff1ad}small,pre{overflow-wrap:anywhere;white-space:pre-wrap}@media(max-width:750px){.compare{display:block}.cells{margin-top:12px}}</style>
